import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene();
scene.fog=new THREE.FogExp2(0x9aaca4,0.0031);
const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.1,1100);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.13;
scene.background=new THREE.Color(0x9aaca4);
scene.add(new THREE.HemisphereLight(0xc5d5d5,0x354338,2.1));
const sun=new THREE.DirectionalLight(0xffd5a0,3.2);sun.position.set(-85,130,-45);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-160;sun.shadow.camera.right=160;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-160;sun.shadow.bias=-.0002;scene.add(sun);
const fill=new THREE.DirectionalLight(0x8db7bd,.75);fill.position.set(100,50,80);scene.add(fill);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const hash=(x,z)=>{let n=Math.sin(x*127.1+z*311.7)*43758.5453;return n-Math.floor(n)};
function heightAt(x,z){const broad=2.2+Math.sin(x*.021+1)*1.5+Math.cos(z*.018)*1.7+Math.sin((x+z)*.025)*.8;const ridges=5.8*Math.exp(-((x+105)**2/4200+(z+95)**2/6400))+7*Math.exp(-((x-120)**2/5300+(z-80)**2/4200))+4*Math.exp(-((x+100)**2/4800+(z-120)**2/4300));const hill=12*Math.exp(-((x-77)**2/1500+(z+120)**2/2200))+8*Math.exp(-((x+75)**2/1900+(z+5)**2/1500));const valley=-7*Math.exp(-((x-24)**2/850+(z+52)**2/1400));const local=1.1*(Math.sin(x*.11+z*.075)*Math.cos(z*.09-x*.06));return broad+ridges+hill+valley+local;}
function makeGroundTexture(){const c=document.createElement('canvas');c.width=c.height=512;const cx=c.getContext('2d'),im=cx.createImageData(512,512);for(let y=0;y<512;y++)for(let x=0;x<512;x++){const i=(y*512+x)*4,n=hash(x*.22,y*.22),n2=hash(x*.055,y*.055),shade=clamp(0.75+n*.42+n2*.22,.55,1.25);im.data[i]=Math.round(71*shade);im.data[i+1]=Math.round(91*shade);im.data[i+2]=Math.round(59*shade);im.data[i+3]=255;}cx.putImageData(im,0,0);const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(28,28);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=4;return t;}
const groundMat=new THREE.MeshStandardMaterial({map:makeGroundTexture(),roughness:1});
const terrainGeo=new THREE.PlaneGeometry(440,440,220,220);terrainGeo.rotateX(-Math.PI/2);const pos=terrainGeo.attributes.position;for(let i=0;i<pos.count;i++)pos.setY(i,heightAt(pos.getX(i),-pos.getZ(i)));terrainGeo.computeVertexNormals();const terrain=new THREE.Mesh(terrainGeo,groundMat);terrain.receiveShadow=true;scene.add(terrain);
// Dawn sky gradient and distant, layered Cascade ridgelines.
const skyGeo=new THREE.SphereGeometry(800,32,18);const skyPos=skyGeo.attributes.position;const skyColors=[];const topCol=new THREE.Color(0x314d55),midCol=new THREE.Color(0xa6b8ad),sunCol=new THREE.Color(0xe5bd8e);for(let i=0;i<skyPos.count;i++){const y=skyPos.getY(i)/800,t=clamp((y+.03)/.96,0,1);const c=new THREE.Color().copy(midCol).lerp(topCol,t);if(y<.08)c.lerp(sunCol,Math.max(0,1-Math.abs(y-.015)*11)*.36);skyColors.push(c.r,c.g,c.b);}skyGeo.setAttribute('color',new THREE.Float32BufferAttribute(skyColors,3));const sky=new THREE.Mesh(skyGeo,new THREE.MeshBasicMaterial({vertexColors:true,side:THREE.BackSide,depthWrite:false}));scene.add(sky);
function ridge(points,color,opacity=1){const verts=[];for(const [x,z,y] of points)verts.push(x,y,z);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));const m=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color,transparent:opacity<1,opacity,side:THREE.DoubleSide}));scene.add(m);}
// broad silhouettes framed against the dawn sky
ridge([[-350,-230,37],[-310,-230,110],[-275,-230,62],[-236,-230,142],[-195,-230,72],[-145,-230,126],[-90,-230,57],[-30,-230,125],[32,-230,60],[92,-230,143],[150,-230,78],[210,-230,125],[265,-230,58],[315,-230,105],[350,-230,42],[-350,-230,0]],0x586f6c);
ridge([[-350,-240,26],[-310,-240,78],[-275,-240,47],[-236,-240,99],[-190,-240,44],[-130,-240,87],[-82,-240,35],[-22,-240,93],[48,-240,42],[110,-240,100],[162,-240,47],[220,-240,86],[275,-240,36],[330,-240,72],[350,-240,0],[-350,-240,0]],0x71857c,.8);
// Natural lake nestled in the low meadow.
const lake=new THREE.Mesh(new THREE.CircleGeometry(37,80),new THREE.MeshPhysicalMaterial({color:0x527f83,roughness:.22,metalness:.1,clearcoat:.9,clearcoatRoughness:.16,transparent:true,opacity:.91}));lake.rotation.x=-Math.PI/2;lake.scale.set(1.48,1,1);lake.position.set(24,2.2,-52);scene.add(lake);
const shore=new THREE.Mesh(new THREE.RingGeometry(35.5,39.4,80),new THREE.MeshStandardMaterial({color:0xb5aa83,roughness:1}));shore.rotation.x=-Math.PI/2;shore.scale.set(1.43,1,1);shore.position.set(24,2.28,-52);scene.add(shore);
// A winding dirt trail, slightly raised from the ground.
const trailPoints=[new THREE.Vector3(0,0,82),new THREE.Vector3(-4,0,55),new THREE.Vector3(-10,0,28),new THREE.Vector3(-8,0,2),new THREE.Vector3(3,0,-18),new THREE.Vector3(10,0,-40),new THREE.Vector3(23,0,-62),new THREE.Vector3(33,0,-79),new THREE.Vector3(43,0,-96)];const trailCurve=new THREE.CatmullRomCurve3(trailPoints);const roadVerts=[],roadUvs=[],roadIndices=[];const roadN=220;for(let i=0;i<=roadN;i++){const t=i/roadN,p=trailCurve.getPoint(t),tan=trailCurve.getTangent(t),side=new THREE.Vector3(-tan.z,0,tan.x).normalize();for(let s of [-1,1]){const x=p.x+side.x*2.7*s,z=p.z+side.z*2.7*s;roadVerts.push(x,heightAt(x,z)+.12,z);roadUvs.push(s*.5+.5,t*14);if(i<roadN){const a=i*2,b=a+1,c=a+2,d=a+3;roadIndices.push(a,c,b,b,c,d);}}}const rg=new THREE.BufferGeometry();rg.setAttribute('position',new THREE.Float32BufferAttribute(roadVerts,3));rg.setAttribute('uv',new THREE.Float32BufferAttribute(roadUvs,2));rg.setIndex(roadIndices);rg.computeVertexNormals();const roadMat=new THREE.MeshStandardMaterial({color:0x8c795c,roughness:1,side:THREE.DoubleSide});const road=new THREE.Mesh(rg,roadMat);road.receiveShadow=true;scene.add(road);
// Trail edges: small embedded stones and periodic timber waymarkers.
const stoneGeo=new THREE.DodecahedronGeometry(1,0),stoneMat=new THREE.MeshStandardMaterial({color:0x77796c,roughness:.94});for(let i=0;i<42;i++){const t=.025+i*.022,p=trailCurve.getPoint(Math.min(t,.95)),tan=trailCurve.getTangent(Math.min(t,.95)),s=i%2?1:-1,x=p.x-tan.z*4.2*s,z=p.z+tan.x*4.2*s;const rock=new THREE.Mesh(stoneGeo,stoneMat);rock.position.set(x,heightAt(x,z)+.22,z);rock.scale.set(.2+hash(i,8)*.25,.17+hash(i,9)*.18,.19+hash(i,11)*.27);rock.rotation.set(hash(i,1),hash(i,2),hash(i,3));rock.castShadow=true;scene.add(rock);}

