// Trail edges: small embedded stones and periodic timber waymarkers.
const stoneGeo=new THREE.DodecahedronGeometry(1,0),stoneMat=new THREE.MeshStandardMaterial({color:0x77796c,roughness:.94});for(let i=0;i<42;i++){const t=.025+i*.022,p=trailCurve.getPoint(Math.min(t,.95)),tan=trailCurve.getTangent(Math.min(t,.95)),s=i%2?1:-1,x=p.x-tan.z*4.2*s,z=p.z+tan.x*4.2*s;const rock=new THREE.Mesh(stoneGeo,stoneMat);rock.position.set(x,heightAt(x,z)+.22,z);rock.scale.set(.2+hash(i,8)*.25,.17+hash(i,9)*.18,.19+hash(i,11)*.27);rock.rotation.set(hash(i,1),hash(i,2),hash(i,3));rock.castShadow=true;scene.add(rock);}
// Evergreen canopy with rich variation in silhouette, scale and color.
const barkMat=new THREE.MeshStandardMaterial({color:0x584737,roughness:1});const pineGeo=new THREE.ConeGeometry(1,1,7,1);pineGeo.translate(0,.5,0);const pineMats=[0x304c3e,0x3c5a48,0x425d4a,0x28473d].map(color=>new THREE.MeshStandardMaterial({color,roughness:.92}));
const trunkInstances=[],foliageInstances=[[],[],[]],treeDummy=new THREE.Object3D();let treeCount=0;for(let i=0;i<700;i++){const x=(hash(i,17)-.5)*390,z=(hash(i,83)-.5)*390;const p=trailCurve.getPoint(clamp((z-82)/-178,0,1));const roadDist=Math.hypot(x-p.x,z-p.z);const lakeDist=Math.hypot((x-24)/1.45,z+52);if(roadDist<7.2||lakeDist<43||Math.abs(x)>208||Math.abs(z)>205)continue;const y=heightAt(x,z),scale=.78+hash(i,21)*1.28;treeDummy.position.set(x,y,z);treeDummy.rotation.set(0,hash(i,23)*6.28,0);treeDummy.scale.set(1,scale,1);treeDummy.updateMatrix();trunkInstances.push({matrix:treeDummy.matrix.clone(),color:new THREE.Color().setHSL(.08,.26,.18+hash(i,22)*.07)});for(let layer=0;layer<3;layer++){const h=scale*(2.5-layer*.52),rad=scale*(1.12-layer*.2);treeDummy.position.set(x,y+scale*(1.1+layer*.73),z);treeDummy.scale.set(rad,h,rad);treeDummy.rotation.y=hash(i+layer,32)*6.28;treeDummy.updateMatrix();foliageInstances[layer].push({matrix:treeDummy.matrix.clone(),color:new THREE.Color(pineMats[Math.floor(hash(i,26)*pineMats.length)].color).offsetHSL((hash(i,27)-.5)*.045,0,(hash(i,29)-.5)*.095)});}treeCount++;}
const trunks=new THREE.InstancedMesh(new THREE.CylinderGeometry(.13,.25,1,7),barkMat,trunkInstances.length);trunks.castShadow=true;trunks.receiveShadow=true;trunkInstances.forEach((v,i)=>{trunks.setMatrixAt(i,v.matrix);trunks.setColorAt(i,v.color)});scene.add(trunks);
